def transform(grid):
    h,w=len(grid),len(grid[0]);out=[r[:] for r in grid]
    # For each 8-connected drawing, add its one-cell bounding frame in 2.
    seen=set();objects=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=1 or (r,c) in seen:continue
        st=[(r,c)];seen.add((r,c));pts=[]
        while st:
          y,x=st.pop();pts.append((y,x))
          for dy in (-1,0,1):
            for dx in (-1,0,1):
              yy,xx=y+dy,x+dx
              if (dy or dx) and 0<=yy<h and 0<=xx<w and grid[yy][xx]==1 and (yy,xx) not in seen:
                seen.add((yy,xx));st.append((yy,xx))
        objects.append(pts)
    # Fill zeros in the interior of an object's bounding rectangle in 3, while
    # preserving zeros that are part of a hole pattern explicitly enclosed by 1s.
    for pts in objects:
      r0=min(y for y,x in pts);r1=max(y for y,x in pts)
      c0=min(x for y,x in pts);c1=max(x for y,x in pts)
      # Only process contours that bound a genuine cavity, not the open simple demo.
      sub=[[grid[y][x] for x in range(c0,c1+1)] for y in range(r0,r1+1)]
      sh,sw=len(sub),len(sub[0]);seen0=set();cav=[]
      for y in range(sh):
        for x in range(sw):
          if sub[y][x]!=0 or (y,x) in seen0:continue
          st=[(y,x)];seen0.add((y,x));part=[];edge=False
          while st:
            a,b=st.pop();part.append((a,b));edge|=a in(0,sh-1) or b in(0,sw-1)
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              aa,bb=a+dy,b+dx
              if 0<=aa<sh and 0<=bb<sw and sub[aa][bb]==0 and (aa,bb) not in seen0:seen0.add((aa,bb));st.append((aa,bb))
          if not edge:cav.extend((r0+a,c0+b) for a,b in part)
      a=max(0,r0-1);b=min(h-1,r1+1);l=max(0,c0-1);q=min(w-1,c1+1)
      if not cav:continue
      for y in range(a,b+1):
        for x in range(l,q+1):
          if (y in (a,b) or x in (l,q)) and grid[y][x]==0:out[y][x]=2
      for y,x in cav:out[y][x]=3
    return out

